#!/usr/bin/env bash
# ==============================================================================
# Global Antigravity Flow Skill Suite - Universal Self-Contained Installer
# Deploys the complete 10-Phase Engineering Lifecycle & GEMINI.md Prime Directives
# Target OS: Ubuntu / Linux / macOS
# ==============================================================================
set -euo pipefail

CONFIG_DIR="${HOME}/.gemini/config"
SKILLS_DIR="${CONFIG_DIR}/skills"
COMPAT_DIR="${HOME}/.gemini/antigravity"

echo "================================================================="
echo " Deploying Antigravity Global Flow Skills Suite"
echo " Target Directory: ${CONFIG_DIR}"
echo "================================================================="

# 1. Ensure target directories exist
mkdir -p "${CONFIG_DIR}" "${COMPAT_DIR}"

# 2. Extract embedded skills payload
echo "[+] Extracting embedded skill packages & GEMINI.md rules..."
base64 -d << 'PAYLOAD_EOF' | tar -xzf - -C "${CONFIG_DIR}"

PAYLOAD_EOF

# Move rules/GEMINI.md into place if present
if [ -f "${CONFIG_DIR}/rules/GEMINI.md" ]; then
    cp "${CONFIG_DIR}/rules/GEMINI.md" "${CONFIG_DIR}/GEMINI.md"
fi

# 3. Setup compatibility symlink
ln -sfn "${SKILLS_DIR}" "${COMPAT_DIR}/skills"
echo "[✓] Symlinked ${COMPAT_DIR}/skills -> ${SKILLS_DIR}"

# 4. Verify installation
echo "================================================================="
echo " Installed Skills Inventory in ${SKILLS_DIR}:"
echo "-----------------------------------------------------------------"
ls -la "${SKILLS_DIR}"
echo "================================================================="
echo " [SUCCESS] Global Antigravity Flow Suite successfully deployed!"
echo " Type /flow in any Antigravity CLI session to begin."
echo "================================================================="
